// Curated data for the Sift category scorer. Plain JS (worker runtime + node
// --test compatible). No dependencies.
//
// Split of responsibilities:
//   category.lexicon.js   THIS FILE - hand-curated, human-editable
//   category.phrases.js   generated by category.phrases.build.mjs (corpus)
//
// The scorer never reads src/data/uk-*.json at runtime: the corpus is
// distilled into category.phrases.js (name -> category) plus a derived
// keyword tier. Regenerate with: node workers/lib/category.phrases.build.mjs

// The 8 canonical categories. Mirrored in src/lib/categories.ts (no shared
// build across layers: keep identical).
export const CANONICAL_CATEGORIES = [
  'Chilled',
  'Snacks',
  'Beverages',
  'Produce',
  'Frozen',
  'Bakery',
  'Food Cupboard',
  'Other',
];

// UK and US spellings of the same word. Folding them keeps a title that says
// 'Yoghurt' matching a corpus entry that says 'Yogurt'.
const SPELLING = {
  yoghurt: 'yogurt',
  yoghurts: 'yogurts',
  mould: 'mold',
  moulds: 'molds',
  colour: 'color',
  colours: 'colors',
  flavour: 'flavor',
  flavours: 'flavors',
  savoury: 'savory',
};

export function normalise(text) {
  return String(text || '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim()
    .replace(/\s+/g, ' ')
    .split(' ')
    .filter(Boolean)
    .map((token) => SPELLING[token] || token)
    .join(' ');
}

